const agora = new Date().getTime();

// Se a API retornar vazio ou o primeiro item não tiver os dados necessários, não é feriado
if ($input.all().length === 0 || !$input.all()[0].json.hasOwnProperty('start')) {
  return [{ json: { eh_feriado: false } }];
}

// Verifica se algum dos itens retornados coincide com a data atual E é do tipo correto
const feriadoEncontrado = $input.all().some(item => {
  const data = item.json;
  const inicio = new Date(data.start).getTime();
  const fim = new Date(data.finish).getTime();

  // Normaliza o texto para evitar erros de maiúsculas/minúsculas ou espaços extras
  const tipo = data.event_kind ? data.event_kind.trim() : "";

  // Condição 1: Está dentro do horário?
  const noPrazo = agora >= inicio && agora <= fim;

  // Condição 2: É Feriado ou Ponto Facultativo?
  const ehTipoValido = (tipo === "Feriado" || tipo === "Ponto Facultativo");

  return noPrazo && ehTipoValido;
});

return [{ json: { eh_feriado: feriadoEncontrado } }];

