const meta = $('Extrair window.location da busca salva').item.json;
const item = $('Loop Over Items').item.json;
const baseUrl = String($('Variaveis').item.json.glpiBaseUrl || '').replace(/\/+$/, '');
const html = String($json.data ?? $json.body ?? '');

function decodeHtml(valor) {
  return String(valor ?? '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

function stripTags(valor) {
  return decodeHtml(String(valor ?? '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizar(valor) {
  return stripTags(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function absolutizar(url) {
  url = decodeHtml(url || '').trim();
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return baseUrl + url;
  return `${baseUrl}/glpi/${url.replace(/^\/+/, '')}`;
}

function safeDecode(valor) {
  const texto = String(valor ?? '');
  try { return decodeURIComponent(texto); } catch (e) { return texto; }
}

function idsDeTicketsNoHtml(htmlRaw) {
  const ids = new Set();
  const patterns = [
    /ticket\.form\.php\?id=(\d+)/gi,
    /front\/ticket\.form\.php\?id=(\d+)/gi,
    /data-itemtype=["']Ticket["'][^>]*data-id=["']?(\d+)["']?/gi,
    /data-id=["']?(\d+)["']?[^>]*data-itemtype=["']Ticket["']/gi
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(htmlRaw)) !== null) ids.add(String(match[1]));
  }

  return Array.from(ids);
}

function extrairHrefDaTag(tag) {
  const m = String(tag || '').match(/\bhref\s*=\s*(['"])(.*?)\1/i);
  return m ? decodeHtml(m[2]) : '';
}

function extrairLinksCsvTodasPaginas(htmlRaw) {
  const candidatos = [];
  const anchorRegex = /<a\b[^>]*href\s*=\s*(['"])([\s\S]*?)\1[^>]*>([\s\S]*?)<\/a>/gi;
  let match;

  while ((match = anchorRegex.exec(htmlRaw)) !== null) {
    const tagInteira = match[0];
    const href = extrairHrefDaTag(tagInteira);
    if (!href) continue;

    const hrefDecoded = safeDecode(decodeHtml(href));
    if (!/report\.dynamic\.php/i.test(hrefDecoded)) continue;
    if (!/item_type=Ticket/i.test(hrefDecoded)) continue;

    const texto = normalizar(match[3]);
    const isTodasPaginasCsvTexto = texto.includes('todas') && texto.includes('paginas') && texto.includes('csv');
    const isDisplayTypeMenos3 = /(?:^|[?&])display_type=-3(?:&|$)/i.test(hrefDecoded);

    if (!isTodasPaginasCsvTexto && !isDisplayTypeMenos3) continue;

    candidatos.push({
      href: absolutizar(href),
      score: (isTodasPaginasCsvTexto ? 100 : 0) + (isDisplayTypeMenos3 ? 100 : 0),
      texto,
      decoded: hrefDecoded
    });
  }

  // Fallback: procurar qualquer report.dynamic.php com display_type=-3, mesmo fora de <a>.
  const reportRegex = /([^"'<>\s]*report\.dynamic\.php\?[^"'<>\s]*display_type=-3[^"'<>\s]*)/gi;
  while ((match = reportRegex.exec(htmlRaw)) !== null) {
    const href = decodeHtml(match[1]);
    const decoded = safeDecode(href);
    if (!/item_type=Ticket/i.test(decoded)) continue;
    candidatos.push({ href: absolutizar(href), score: 50, texto: 'fallback_display_type_-3', decoded });
  }

  const vistos = new Set();
  return candidatos
    .filter(c => {
      const key = safeDecode(c.href);
      if (vistos.has(key)) return false;
      vistos.add(key);
      return true;
    })
    .sort((a, b) => b.score - a.score);
}

function itemVazio(motivo, extras = {}) {
  return [{
    json: {
      ...item,
      baixar_csv: false,
      pesquisa_vazia: true,
      motivo,
      ...extras,
      ID: '',
      'Título': '',
      Status: '',
      'Última atualização': '',
      'Data de abertura': '',
      Prioridade: '',
      'Atribuído - Grupo técnico': '',
      'Atribuído - Técnico': '',
      'Tempo para solução + Progresso': '',
      'Tempo para resolver excedido': ''
    },
    pairedItem: { item: 0 }
  }];
}

const texto = stripTags(html);
const textoNorm = texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const pareceLogin =
  /name=["']?login_name/i.test(html) ||
  /login_password/i.test(html) ||
  (textoNorm.includes('login') && textoNorm.includes('senha'));

if (pareceLogin) {
  return itemVazio('pagina_ticket_retornou_tela_de_login', {
    erro_glpi: 'A URL extraída de window.location retornou tela de login. Cookie/sessão GLPI possivelmente inválido.',
    link_pesquisa_html: meta.link_pesquisa_html
  });
}

const idsPesquisaHtml = idsDeTicketsNoHtml(html);

const semResultados =
  textoNorm.includes('nenhum item encontrado') ||
  textoNorm.includes('nenhum elemento encontrado') ||
  textoNorm.includes('nenhum registro encontrado') ||
  textoNorm.includes('nao ha itens') ||
  textoNorm.includes('não há itens') ||
  textoNorm.includes('sem resultado') ||
  textoNorm.includes('sem resultados') ||
  textoNorm.includes('0 item') ||
  textoNorm.includes('0 resultado') ||
  /0\s*-\s*0\s*\/\s*0/.test(texto);

if (!idsPesquisaHtml.length || semResultados) {
  return itemVazio('busca_salva_sem_chamados_atuais_no_html', {
    ids_pesquisa_html: idsPesquisaHtml,
    total_chamados_html: idsPesquisaHtml.length,
    link_pesquisa_html: meta.link_pesquisa_html,
    savedsearch_window_location: meta.savedsearch_window_location
  });
}

const candidatosCsv = extrairLinksCsvTodasPaginas(html);

if (!candidatosCsv.length) {
  return itemVazio('link_todas_paginas_csv_nao_encontrado_no_html_ticket', {
    ids_pesquisa_html: idsPesquisaHtml,
    total_chamados_html: idsPesquisaHtml.length,
    link_pesquisa_html: meta.link_pesquisa_html,
    debug_html_export: html.slice(Math.max(0, html.indexOf('dropdown-export') - 500), html.indexOf('dropdown-export') + 5000)
  });
}

const escolhido = candidatosCsv[0];

return [{
  json: {
    ...item,
    baixar_csv: true,
    pesquisa_vazia: false,
    ids_pesquisa_html: idsPesquisaHtml,
    total_chamados_html: idsPesquisaHtml.length,
    link: escolhido.href,
    link_pesquisa_html: meta.link_pesquisa_html,
    savedsearch_window_location: meta.savedsearch_window_location,
    savedsearch_carregada_na_sessao: item.id_glpi,
    link_exportacao_tipo: 'html_ticket_botao_todas_paginas_csv',
    link_exportacao_score: escolhido.score,
    link_exportacao_texto: escolhido.texto,
    link_exportacao_preview: safeDecode(escolhido.href).slice(0, 1000)
  },
  pairedItem: { item: 0 }
}];

const meta = $('Validar resultado da pesquisa').item.json;
const rows = $input.all().map(i => i.json || {});
const idsPermitidos = new Set((meta.ids_pesquisa_html || []).map(id => String(id).trim()).filter(Boolean));

function normalizar(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

const validos = rows.filter(row => {
  const id = String(row.ID ?? '').trim();
  if (!/^\d+$/.test(id)) return false;

  // Proteção final: só deixa passar chamados vistos no HTML da busca salva atual.
  if (idsPermitidos.size > 0 && !idsPermitidos.has(id)) return false;

  return true;
});

if (!validos.length) {
  return [{
    json: {
      id_glpi: meta.id_glpi,
      grupo: meta.grupo,
      baixar_csv: false,
      pesquisa_vazia: true,
      motivo: 'csv_sem_linhas_validas_para_a_busca_salva_atual',
      link_csv_usado: meta.link,
      link_pesquisa_html: meta.link_pesquisa_html,
      ID: '',
      'Título': '',
      Status: '',
      'Última atualização': '',
      'Data de abertura': '',
      Prioridade: '',
      'Atribuído - Grupo técnico': '',
      'Atribuído - Técnico': '',
      'Tempo para solução + Progresso': '',
      'Tempo para resolver excedido': ''
    },
    pairedItem: { item: 0 }
  }];
}

return validos.map((row, index) => ({
  json: {
    ...row,
    id_glpi: String(meta.id_glpi),
    grupo: meta.grupo,
    __id_glpi_validado: String(meta.id_glpi),
    __grupo_validado: meta.grupo,
    __validado_por_ids_html: idsPermitidos.size > 0,
    __link_csv_usado: meta.link,
    __link_pesquisa_html: meta.link_pesquisa_html,
    __savedsearch_carregada_na_sessao: meta.savedsearch_carregada_na_sessao
  },
  pairedItem: { item: index }
}));

const item = $('Loop Over Items').item.json;
const baseUrl = String($('Variaveis').item.json.glpiBaseUrl || '').replace(/\/+$/, '');
const html = String($json.data ?? $json.body ?? '');

function decodeHtml(valor) {
  return String(valor ?? '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

function stripTags(valor) {
  return decodeHtml(String(valor ?? '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim();
}

function absolutizar(url) {
  url = decodeHtml(url || '').trim();
  if (!url) return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return baseUrl + url;
  return `${baseUrl}/glpi/${url.replace(/^\/+/, '')}`;
}

function getHeader(headers, nome) {
  headers = headers || {};
  const alvo = String(nome).toLowerCase();
  for (const key of Object.keys(headers)) {
    if (String(key).toLowerCase() === alvo) {
      const v = headers[key];
      return Array.isArray(v) ? String(v[0] || '') : String(v || '');
    }
  }
  return '';
}

const texto = stripTags(html);
const textoNorm = texto.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const pareceLogin =
  /name=["']?login_name/i.test(html) ||
  /login_password/i.test(html) ||
  (textoNorm.includes('login') && textoNorm.includes('senha'));

function retornoVazio(motivo, extras = {}) {
  // Fallback controlado: evita quebrar URL vazia no próximo HTTP Request.
  return [{
    json: {
      ...item,
      link_pesquisa_html: `${baseUrl}/glpi/front/ticket.php?savedsearches_id=${encodeURIComponent(String(item.id_glpi))}&itemtype=Ticket&reset=reset`,
      aviso_extracao_window_location: motivo,
      ...extras
    },
    pairedItem: { item: 0 }
  }];
}

if (pareceLogin) {
  return retornoVazio('savedsearch_retornou_tela_de_login', {
    erro_glpi: 'A requisição savedsearch.php?action=load retornou tela de login. Cookie/sessão GLPI possivelmente inválido.'
  });
}

let location = '';

// Caso o servidor algum dia use redirect HTTP real.
location = getHeader($json.headers || $json.responseHeaders || {}, 'location');

// Caso atual observado: HTML com JavaScript window.location='...ticket.php?...criteria...'.
if (!location) {
  const matches = [...html.matchAll(/window\.location(?:\.href)?\s*=\s*(['"])([\s\S]*?)\1/gi)];
  const escolhido = matches
    .map(m => decodeHtml(m[2]))
    .find(v => /\/glpi\/front\/ticket\.php/i.test(v) || /ticket\.php/i.test(v));
  location = escolhido || '';
}

// Fallback para document.location/assign, se aparecer em outra versão do GLPI.
if (!location) {
  const m = html.match(/(?:document\.)?location(?:\.href)?\s*=\s*(['"])([\s\S]*?ticket\.php[\s\S]*?)\1/i)
    || html.match(/location\.assign\(\s*(['"])([\s\S]*?ticket\.php[\s\S]*?)\1\s*\)/i);
  if (m) location = decodeHtml(m[2]);
}

if (!location) {
  return retornoVazio('window_location_nao_encontrado_no_html_da_savedsearch', {
    debug_html_inicio: html.slice(0, 1500)
  });
}

const linkPesquisaHtml = absolutizar(location);

return [{
  json: {
    ...item,
    link_pesquisa_html: linkPesquisaHtml,
    savedsearch_window_location: location,
    savedsearch_carregada_na_sessao: item.id_glpi
  },
  pairedItem: { item: 0 }
}];

