// Envio individual de chamados ATRASADOS para técnicos
// Escopo restrito aos relatórios/grupos GLPI vindos do filtro: 311 e 327.

const ID_GLPI_PERMITIDOS = new Set(["311", "327"]);

const inputItems = $input.all().map(i => i.json || {});

// Acumula todos os chamados de todos os itens válidos de entrada
let todosOsChamados = [];
for (const item of inputItems) {
  const idGlpiAtual = String(item.id_glpi ?? '').trim();
  if (ID_GLPI_PERMITIDOS.has(idGlpiAtual) && Array.isArray(item.chamados_individuais)) {
    const chamadosDoItem = item.chamados_individuais.map(c => ({
      ...c,
      __id_glpi_container: idGlpiAtual
    }));
    todosOsChamados = todosOsChamados.concat(chamadosDoItem);
  }
}

if (!todosOsChamados.length) {
  return [{ json: { tecnicos: [], motivo: 'sem_chamados_ou_fora_do_escopo' } }];
}

const hoje = new Date().toLocaleDateString('pt-BR');

// MAPEAMENTO DE CONTATOS INDIVIDUAIS
// Vem do node "Edit Fields - Contatos e menções", para manter nomes/números fora deste código.
const mapaContatos = inputItems.find(item => item.mapaContatosTecnicos)?.mapaContatosTecnicos ?? {};

function normalizarTexto(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function parseProgresso(progressoRaw) {
  const bruto = String(progressoRaw ?? '');
  const matchTempo = bruto.match(/^(\d{2}-\d{2}-\d{4}\s+\d{2}:\d{2})/);
  const matchPct = bruto.match(/(\d{1,3})\s*%/);
  return {
    tempoSolucao: matchTempo ? matchTempo[1] : (bruto.split('\n')[0] || '').trim(),
    porcentagem: matchPct ? Number(matchPct[1]) : 0,
  };
}

function calcularTempoAtrasado(tempoSolucao) {
  if (!tempoSolucao) return '';
  const part = String(tempoSolucao).split(/[- :]/);
  if (part.length < 5) return '';

  const isoString = `${part[2]}-${part[1].padStart(2, '0')}-${part[0].padStart(2, '0')}T${part[3].padStart(2, '0')}:${part[4].padStart(2, '0')}:00-03:00`;
  const limite = new Date(isoString);
  if (Number.isNaN(limite.getTime())) return '';

  const diffMs = new Date() - limite;
  if (diffMs <= 0) return '';

  const dias = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const horas = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  return `${dias}d ${horas}h`;
}

function obterGrupoTecnicoRaw(row) {
  const direto = row['Atribuído - Grupo técnico'];
  if (direto !== undefined && direto !== null && String(direto).trim() !== '') return direto;

  for (const chave of Object.keys(row || {})) {
    const chaveNorm = normalizarTexto(chave);
    if (chaveNorm.includes('grupo') && chaveNorm.includes('tecnico')) {
      const valor = row[chave];
      if (valor !== undefined && valor !== null && String(valor).trim() !== '') return valor;
    }
  }
  return '';
}

function ehChamadoDoEscopoCoordInfra(row) {
  const origem = String(row.__id_glpi_origem ?? row.__id_glpi_container ?? '').trim();
  if (origem === '311' || origem === '327') return true;

  const grupoNorm = normalizarTexto(obterGrupoTecnicoRaw(row));
  return grupoNorm.includes('infraestrutura') || grupoNorm.includes('coordenacao infra');
}

function ehAtrasado(row) {
  const statusNorm = normalizarTexto(row.Status);

  // Se está aguardando o requerente (pendente), ignora e não notifica o técnico
  if (statusNorm.includes('pendente')) return false;

  const excedidoNorm = normalizarTexto(row['Tempo para resolver excedido']);
  const progressoRaw = row['Tempo para solução + Progresso'] || row['Tempo para solution + Progresso'] || '';
  const { porcentagem } = parseProgresso(progressoRaw);

  return statusNorm.includes('atrasado') || excedidoNorm === 'sim' || porcentagem >= 100;
}

function extrairTecnicos(tecnicoRaw) {
  if (!tecnicoRaw || normalizarTexto(tecnicoRaw) === 'nan') return [];
  return String(tecnicoRaw)
    .split('<br>')
    .map(nome => nome.trim())
    .filter(Boolean)
    .map(nomeCompleto => ({
      nomeCompleto,
      primeiroNome: nomeCompleto.split(/\s+/)[0],
    }));
}

const chamadosPorTecnico = {};
const tecnicosSemContato = new Set();

for (const chamado of todosOsChamados) {
  if (!chamado.ID || !ehChamadoDoEscopoCoordInfra(chamado) || !ehAtrasado(chamado)) continue;

  const tecnicos = extrairTecnicos(chamado['Atribuído - Técnico']);
  if (!tecnicos.length) continue;

  const progressoRaw = chamado['Tempo para solução + Progresso'] || chamado['Tempo para solution + Progresso'] || '';
  const { tempoSolucao, porcentagem } = parseProgresso(progressoRaw);
  const tempoAtrasado = calcularTempoAtrasado(tempoSolucao);
  const linkFinal = `https://glpi.suaempresa.com/glpi/front/ticket.form.php?id=${chamado.ID}`;
  const nivel = chamado.__nivel_infra ? `[${chamado.__nivel_infra}] ` : '';

  let metaTempo = '';
  if (tempoAtrasado) {
    metaTempo = ` — atrasado há ${tempoAtrasado}`;
  }

  for (const tecnico of tecnicos) {
    const contato = mapaContatos[tecnico.primeiroNome];
    if (!contato) {
      tecnicosSemContato.add(tecnico.primeiroNome);
      continue;
    }

    if (!chamadosPorTecnico[tecnico.primeiroNome]) {
      chamadosPorTecnico[tecnico.primeiroNome] = [];
    }

    chamadosPorTecnico[tecnico.primeiroNome].push(
      `${nivel}🔴 *Chamado ATRASADO:* ${chamado.ID}\n` +
      `📌 *Título:* ${chamado['Título'] || 'Sem título'}\n` +
      `🔗 ${linkFinal}\n` +
      `📅 *Abertura:* ${chamado['Data de abertura'] || ''}\n` +
      `⏱️ *Limite/SLA:* ${tempoSolucao || 'não informado'}${metaTempo}\n` +
      `📊 *Progresso:* ${porcentagem}%`
    );
  }
}

const payloadEnvio = [];

for (const [nome, listaChamados] of Object.entries(chamadosPorTecnico)) {
  let msg = `*Olá, ${nome}!*\n\n`;
  msg += `Você possui *${listaChamados.length} chamado(s) atrasado(s)* atribuído(s) a você no GLPI da empresa em *${hoje}*.\n\n`;
  msg += listaChamados.join('\n\n');
  msg += `\n\n_Por favor, verifique e atualize o atendimento no GLPI._\n`;
  msg += `🤖 _Esta é uma mensagem automática gerada pelo sistema._`;

  payloadEnvio.push({
    tecnico: nome,
    number: mapaContatos[nome],
    mensagem: msg,
  });
}

return [{
  json: {
    tecnicos: payloadEnvio,
    total_tecnicos_com_envio: payloadEnvio.length,
    total_chamados_atrasados_para_envio: Object.values(chamadosPorTecnico).reduce((acc, lista) => acc + lista.length, 0),
    tecnicos_sem_contato: Array.from(tecnicosSemContato)
  }
}];

// 1. Acessa os dados estáticos do workflow para persistência entre pulsos
const staticData = $getWorkflowStaticData('global');

// 2. Obtém o ID desta execução específica (reseta a cada rodada do workflow)
const execId = $executionId;

// 3. Verifica se esta execução já enviou o sinal de 'concluído'
if (staticData.lastExecId === execId) {
  return [{ json: { status: "execucao_duplicada" } }];
}

// 4. Primeiro pulso detectado: registra o ID da execução para bloquear os próximos
staticData.lastExecId = execId;
return [{ json: { status: "permitido" } }];

// Coleta todos os itens do nó anterior
const itensAnteriores = $input.all();

// Cria um JSON único contendo uma lista desses itens
return [{
    json: {
        listaDeDados: itensAnteriores.map(item => item.json)
    }
}];

// 1. Captura todos os itens que chegaram ao node
const all = $input.all().map(i => i.json);

// 2. Tenta obter o grupo/id do Split Out ou do próprio item
const grupo = all[0]?.grupo ?? $node["Split Out"].json["grupo"];
const id_glpi = all[0]?.id_glpi ?? $node["Split Out"].json["id_glpi"];

// 3. FILTRO CRUCIAL: Mantém apenas itens que possuem um ID preenchido
const rows = all.filter(r => r && r.ID && String(r.ID).trim() !== "");

// Funções auxiliares (espelhando o Python)
function todayBR() {
  const d = new Date();
  return `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}/${d.getFullYear()}`;
}

function formatReport(title, group, dateStr, rowsList, header = "") {
  let count = rowsList.length;
  if (rowsList.length === 1 && rowsList[0] === "Não há chamados") {
    count = 0;
  }
  let msg = `${title} - *${group}* (*${count}*) - *${dateStr}*\n`;
  if (header) msg += `\n${header}`;
  msg += rowsList.join("\n");
  return msg;
}

const hoje = todayBR();

// --- CASO: COM CHAMADOS ---
const linhas = [];
const linhasDetalhadas = [];
const tecnicosLista = [];
const _seenTecnicos = new Set();

// Funções de parsing e labels
function extrairTecnicos(tecnicoRaw, seen) {
  if (tecnicoRaw && String(tecnicoRaw).trim().toLowerCase() !== 'nan') {
    const nomesFull = String(tecnicoRaw).split("<br>").map(n => n.trim()).filter(n => n);
    const tecnicoPrincipal = nomesFull[0] || "";
    const novos = [];
    for (const full of nomesFull) {
      const primeiroNome = full.split(" ")[0];
      if (primeiroNome && !seen.has(primeiroNome)) {
        novos.push(primeiroNome);
        seen.add(primeiroNome);
      }
    }
    return { tecnico: tecnicoPrincipal, tecnicoFull: nomesFull.join(", "), novos };
  }
  return { tecnico: "", tecnicoFull: "", novos: [] };
}

function extrairGrupoTecnico(grupoRaw) {
  if (grupoRaw && String(grupoRaw).trim().toLowerCase() !== 'nan') {
    const grupos = String(grupoRaw)
      .split("<br>")
      .map(g => g.trim())
      .filter(g => g)
      .map(g => {
        const partes = g.split(">").map(p => p.trim()).filter(p => p);
        return partes.length ? partes[partes.length - 1] : g;
      });
    return grupos.join(", ");
  }
  return "";
}

function obterGrupoTecnicoRaw(row) {
  const direto = row["Atribuído - Grupo técnico"];
  if (direto !== undefined && direto !== null && String(direto).trim() !== "") {
    return direto;
  }

  const chaves = Object.keys(row || {});
  for (const chave of chaves) {
    const chaveNorm = String(chave)
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase();
    if (chaveNorm.includes("grupo") && chaveNorm.includes("tecnico")) {
      const valor = row[chave];
      if (valor !== undefined && valor !== null && String(valor).trim() !== "") {
        return valor;
      }
    }
  }

  return "";
}

const IDS_INFRA_CONSOLIDAR = new Set(["327", "324", "332"]);

function extrairUltimoGrupo(grupoRaw) {
  if (!grupoRaw || String(grupoRaw).trim().toLowerCase() === 'nan') return "";
  const grupos = String(grupoRaw)
    .split("<br>")
    .map(g => g.trim())
    .filter(g => g)
    .map(g => {
      const partes = g.split(">").map(p => p.trim()).filter(p => p);
      return partes.length ? partes[partes.length - 1] : g;
    });
  return grupos[0] || "";
}

function obterNivelInfra(grupoRaw) {
  const ultimoGrupo = extrairUltimoGrupo(grupoRaw).toLowerCase();
  if (ultimoGrupo.startsWith("n1 - infraestrutura")) return "N1";
  if (ultimoGrupo.startsWith("n2 - infraestrutura")) return "N2";
  if (ultimoGrupo.startsWith("n3 - infraestrutura")) return "N3";
  return "";
}

const is311 = String(id_glpi) === "311";
const isInfraIndividual = IDS_INFRA_CONSOLIDAR.has(String(id_glpi));

if (isInfraIndividual) {
  // Os IDs 327/324/332 serão enviados somente pelo consolidado gerado no 311.
  return [{ json: { skip: true, id_glpi, grupo } }];
}

const rowsPrincipais = [];
const rowsInfraConsolidadas = [];

for (const r of rows) {
  if (!is311) {
    rowsPrincipais.push(r);
    continue;
  }

  const nivelInfra = obterNivelInfra(obterGrupoTecnicoRaw(r));
  if (nivelInfra) {
    rowsInfraConsolidadas.push({ row: r, nivel: nivelInfra });
  } else {
    rowsPrincipais.push(r);
  }
}

// --- CASO: SEM CHAMADOS ---
if (rowsPrincipais.length === 0 && (!is311 || rowsInfraConsolidadas.length === 0)) {
  const msg = formatReport("Chamados em atraso", grupo, hoje, ["Não há chamados"]);

  // Retorna a mensagem inteira em um único item
  return [{
    json: {
      id_glpi,
      grupo,
      mensagem: msg,
      tecnicos_lista: [],
      chamados_individuais: [],
      parte: 1,
      total_partes: 1,
    }
  }];
}

function parseProgresso(progressoRaw) {
  let tempoSolucao = "";
  let porcentagem = 0;
  if (typeof progressoRaw === 'string') {
    // Captura a data/hora no início da string
    const matchTempo = progressoRaw.match(/^(\d{2}-\d{2}-\d{4} \d{2}:\d{2})/);
    if (matchTempo) {
      tempoSolucao = matchTempo[1];
    } else {
      tempoSolucao = progressoRaw.split("\n")[0].trim();
    }
    const matchPct = progressoRaw.match(/(\d{1,3})\s*%/);
    if (matchPct) porcentagem = parseInt(matchPct[1]);
  }
  return { tempoSolucao, porcentagem };
}

// Função para calcular o tempo atrasado
function calcularTempoAtrasado(tempoSolucao) {
  // tempoSolucao no formato "DD-MM-YYYY HH:mm"
  if (!tempoSolucao) return "";
  const part = tempoSolucao.split(/[- :]/);
  if (part.length < 5) return "";
  // Monta string ISO com timezone -03:00 (Brasília)
  const isoString = `${part[2]}-${part[1].padStart(2, '0')}-${part[0].padStart(2, '0')}T${part[3].padStart(2, '0')}:${part[4].padStart(2, '0')}:00-03:00`;
  const limite = new Date(isoString);
  const agora = new Date();
  const diffMs = agora - limite;
  if (diffMs <= 0) return "";
  const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
  return ` (${days}d ${hours}h)`;
}

function determinarStatusLabel(status, excedido, porcentagem) {
  if (status === "Novo") return { emoji: "🔵", label: "Em Aberto" };
  if (status === "Pendente") return { emoji: "⏳", label: "PENDENTE" };
  if (excedido || porcentagem === 100) return { emoji: "🔴", label: `ATRASADO(${porcentagem}%)` };
  if (porcentagem < 50) return { emoji: "🟢", label: `Em Atendimento(${porcentagem}%)` };
  if (porcentagem < 70) return { emoji: "🟡", label: `Atenção(${porcentagem}%)` };
  if (porcentagem < 100) return { emoji: "🟠", label: `Atenção(${porcentagem}%)` };
  return { emoji: "🔴", label: "ATRASADO" };
}

// Processa as linhas
for (const r of rowsPrincipais) {
  const idChamado = r["ID"] || "";
  const tecnicoRaw = r["Atribuído - Técnico"] || "";
  const grupoTecnicoRaw = obterGrupoTecnicoRaw(r);
  const { tecnico, tecnicoFull, novos } = extrairTecnicos(tecnicoRaw, _seenTecnicos);
  const grupoTecnico = extrairGrupoTecnico(grupoTecnicoRaw);
  if (novos) tecnicosLista.push(...novos);

  const status = r["Status"] || "";
  const dataAbertura = r["Data de abertura"] || "";
  const progressoRaw = r["Tempo para solução + Progresso"] || "";
  const excedido = String(r["Tempo para resolver excedido"] || "").trim().toLowerCase() === "sim";

  const { tempoSolucao, porcentagem } = parseProgresso(progressoRaw);
  const TituloChamado = r["Título"] || "Sem título";
  const linkFinal = `https://glpi.suaempresa.com/glpi/front/ticket.form.php?id=${idChamado}`;
  const { emoji, label: statusLabel } = determinarStatusLabel(status, excedido, porcentagem);

  let atrasadoText = "";
  if (emoji === "🔴") {
    atrasadoText = calcularTempoAtrasado(tempoSolucao);
  }

  let labelTecnico = tecnicoFull;
  if (status === "Novo" && !tecnico) labelTecnico = "[NOVO]";

  const dataAtt = r['Última atualização'] || '';
  let pendenteText = '';
  if (status === 'Pendente' && dataAtt) {
    try {
      const part = dataAtt.split(/[- :]/); // DD-MM-YYYY HH:mm
      const dtAtt = new Date(part[2], part[1]-1, part[0], part[3], part[4]);
      const diffMs = new Date() - dtAtt;
      const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
      const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      pendenteText = ` (${days}d ${hours}h)`;
    } catch(e) {}
  }

  let tempoSolucaoText = '';
  if (["🟢", "🟡", "🟠"].includes(emoji) && tempoSolucao) {
    tempoSolucaoText = ` (${tempoSolucao})`;
  }
  const textoLinha = `${emoji}${pendenteText}${atrasadoText} (${idChamado}) - ${TituloChamado} - ${linkFinal} - *${labelTecnico}* - ${dataAbertura} - ${tempoSolucao} - ${porcentagem}%${tempoSolucaoText}`;
  linhas.push(textoLinha);

  // Formato detalhado para o ID 311
  if (String(id_glpi) === "311") {
    const bloco = [
      `${emoji} *${statusLabel}${pendenteText}${atrasadoText}*`,
      `- *Grupo técnico:* ${grupoTecnico || "Não informado"}`,
      `- *Título:* ${TituloChamado || 'Sem título'}\n` +
      `- *Link:* ${linkFinal}`,
      `- *ID:* ${idChamado}`,
      `- *Resp:* *${labelTecnico}*`,
      `- *Abertura:* ${dataAbertura}`
    ];
    if (tempoSolucao) bloco.push(`- *Tempo para solução:* ${tempoSolucao}`);
    // Sempre termina com uma quebra de linha
    bloco.push('');
    linhasDetalhadas.push(bloco.join("\n"));
  }
}

let mensagem = "";
if (String(id_glpi) === "311") {
  mensagem = formatReport("Chamados em Atraso", grupo, hoje, linhasDetalhadas, "");
} else {
  mensagem = formatReport("Chamados em Atraso", grupo, hoje, linhas, "STATUS | ID | LINK | RESP | DATA | TEMPO | %\n\n");
}

const mencoes = tecnicosLista.map(nome => `@${nome}`).join(" ");
if (mencoes) mensagem += `\n\n${mencoes}`;

const outputs = [{
  json: {
    id_glpi,
    grupo,
    mensagem: mensagem,
    tecnicos_lista: tecnicosLista,
    chamados_individuais: rowsPrincipais.map(r => ({ ...r, __id_glpi_origem: String(id_glpi), __grupo_origem: grupo })),
    parte: 1,
    total_partes: 1,
  }
}];

if (is311 && rowsInfraConsolidadas.length > 0) {
  const linhasInfra = [];
  const tecnicosInfra = [];
  const seenInfra = new Set();

  for (const item of rowsInfraConsolidadas) {
    const r = item.row;
    const nivel = item.nivel;

    const idChamado = r["ID"] || "";
    const tecnicoRaw = r["Atribuído - Técnico"] || "";
    const { tecnico, tecnicoFull, novos } = extrairTecnicos(tecnicoRaw, seenInfra);
    if (novos) tecnicosInfra.push(...novos);

    const status = r["Status"] || "";
    const dataAbertura = r["Data de abertura"] || "";
    const progressoRaw = r["Tempo para solução + Progresso"] || "";
    const excedido = String(r["Tempo para resolver excedido"] || "").trim().toLowerCase() === "sim";

    const { tempoSolucao, porcentagem } = parseProgresso(progressoRaw);
    const TituloChamado = r["Título"] || "Sem título";
    const linkFinal = `https://glpi.suaempresa.com/glpi/front/ticket.form.php?id=${idChamado}`;
    const { emoji } = determinarStatusLabel(status, excedido, porcentagem);

    let atrasadoText = "";
    if (emoji === "🔴") {
      atrasadoText = calcularTempoAtrasado(tempoSolucao);
    }

    let labelTecnico = tecnicoFull;
    if (status === "Novo" && !tecnico) labelTecnico = "[NOVO]";

    const dataAtt = r['Última atualização'] || '';
    let pendenteText = '';
    if (status === 'Pendente' && dataAtt) {
      try {
        const part = dataAtt.split(/[- :]/); // DD-MM-YYYY HH:mm
        const dtAtt = new Date(part[2], part[1]-1, part[0], part[3], part[4]);
        const diffMs = new Date() - dtAtt;
        const days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
        const hours = Math.floor((diffMs % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        pendenteText = ` (${days}d ${hours}h)`;
      } catch(e) {}
    }

    let tempoSolucaoText = '';
    if (["🟢", "🟡", "🟠"].includes(emoji) && tempoSolucao) {
      tempoSolucaoText = ` (${tempoSolucao})`;
    }

    linhasInfra.push(`[${nivel}] ${emoji}${pendenteText}${atrasadoText} (${idChamado}) - ${TituloChamado} - ${linkFinal} - *${labelTecnico}* - ${dataAbertura} - ${tempoSolucao} - ${porcentagem}%${tempoSolucaoText}`);
  }

  let mensagemInfra = formatReport("Chamados em Atraso", "INFRAESTRUTURA", hoje, linhasInfra, "NIVEL | ID | LINK | RESP | DATA | TEMPO | %\n\n");
  const mencoesInfra = tecnicosInfra.map(nome => `@${nome}`).join(" ");
  if (mencoesInfra) mensagemInfra += `\n\n${mencoesInfra}`;

  outputs.push({
    json: {
      id_glpi: "327",
      ids_glpi_consolidados: [327, 324, 332],
      grupo: "INFRAESTRUTURA",
      mensagem: mensagemInfra,
      tecnicos_lista: tecnicosInfra,
      chamados_individuais: rowsInfraConsolidadas.map(item => ({ ...item.row, __id_glpi_origem: "311", __nivel_infra: item.nivel, __grupo_origem: "INFRAESTRUTURA" })),
      parte: 1,
      total_partes: 1,
    }
  });
}

return outputs;
